/* Botón estilo steampunk */

/* Variables scoped a la clase principal */
.steampunk-btn {
  --bronze-dark: #2b2927;
  --bronze-mid: #63431f;
  --bronze-light: #856233;
  --bronze-highlight: #fce3a1;
  --glass-green-deep: #281d08;
  --glass-green-bright: #544212;
  --amber-light: #ffc95e;
  --amber-glow: #fa9a6a;

  /* Estructura principal y sombra externa del botón */
  position: relative;
  width: 110px;
  height: 110px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  outline: none;
  border-radius: 22px; /* Forma semi-cuadrada */

  /* Sombras del botón completo para darle elevación real */
  box-shadow:
    0 15px 25px rgba(0, 0, 0, 0.8),
    0 5px 10px rgba(0, 0, 0, 0.5),
    inset 0 1px 1px rgba(255, 255, 255, 0.2);

  transition:
    transform 0.15s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.15s ease;
}

/* 2. Marco de Metal Bronce Esculpido */
.steampunk-btn .btn-frame {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 22px;
  padding: 6px; /* Grosor del bisel de bronce */
  box-sizing: border-box;

  /* Gradiente metálico de bronce cepillado */
  background: linear-gradient(
    135deg,
    var(--bronze-highlight) 0%,
    var(--bronze-light) 20%,
    var(--bronze-mid) 45%,
    var(--bronze-dark) 70%,
    var(--bronze-light) 100%
  );

  /* Textura de bisel pulido */
  box-shadow:
    inset 0 2px 3px rgba(255, 255, 255, 0.6),
    inset 0 -3px 5px rgba(0, 0, 0, 0.8),
    inset 2px 2px 4px var(--bronze-highlight),
    inset -2px -2px 4px #000;

  transition: box-shadow 0.1s ease; /* Transición suave para el estado active */
}

/* 3. Lente de Vidrio Verde Oscuro */
.steampunk-btn .btn-glass {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;

  /* Base del vidrio verde */
  background: radial-gradient(
    circle at 50% 50%,
    var(--glass-green-bright) 0%,
    var(--glass-green-deep) 85%
  );

  /* Sombra interior para simular grosor del cristal encajado */
  box-shadow:
    inset 0 0 8px rgba(0, 0, 0, 0.9),
    inset 0 0 15px rgba(0, 0, 0, 0.7),
    0 0 2px rgba(0, 0, 0, 0.5);

  transition:
    background 0.1s ease,
    box-shadow 0.1s ease; /* Transición suave para el estado active */
}

/* 4. Patrón de Red / Malla Steampunk dentro del Vidrio */
.steampunk-btn .glass-pattern {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  opacity: 0.25;
  background-image: radial-gradient(
      var(--bronze-light) 0.5px,
      transparent 0.5px
    ),
    linear-gradient(45deg, transparent 49%, rgb(0, 0, 0) 50%, transparent 51%);
  background-size:
    8px 8px,
    6px 6px;
  mix-blend-mode: overlay;
  pointer-events: none;
}

/* 5. Luz Ámbar Interna (Efecto Filamento/Luz atraviesa Vidrio) */
.steampunk-btn .amber-glow {
  position: absolute;
  width: 70px;
  height: 70px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    var(--amber-light) 0%,
    var(--amber-glow) 40%,
    transparent 75%
  );
  opacity: 0.6;
  filter: blur(6px);
  mix-blend-mode: color-dodge;
  transition:
    opacity 0.3s ease,
    transform 0.3s ease,
    filter 0.3s ease;
}

/* 6. Reflejos Curvos sobre el Vidrio */
.steampunk-btn .glass-reflection {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: 14px;
  pointer-events: none;
}

.steampunk-btn .glass-reflection::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 6px;
  right: 6px;
  height: 40%;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.4) 0%,
    rgba(255, 255, 255, 0.05) 80%,
    transparent 100%
  );
  border-radius: 10px 10px 80% 80% / 8px 8px 15px 15px;
}

/* 7. Tipografía / Texto Metálico con Volumen */
.steampunk-btn .btn-text {
  position: relative;
  z-index: 2;
  font-family: "Georgia", "Times New Roman", serif;
  font-size: 3.1rem;
  font-weight: 50;

  /* Color metálico de bronce en el texto */
  color: var(--bronze-highlight);
  background: linear-gradient(
    180deg,
    #ffffff 0%,
    var(--bronze-highlight) 50%,
    var(--bronze-mid) 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;

  /* Sombras e iluminación proyectada desde la luz interna */
  text-shadow:
    0 2px 4px rgba(0, 0, 0, 0.9),
    0 0 10px var(--amber-light);
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.8));
  user-select: none;
  transition:
    text-shadow 0.3s ease,
    filter 0.3s ease;
}

/* --- EFECTOS HOVER Y ACTIVE --- */

/* Hover: La luz ámbar se intensifica y el botón se eleva suavemente */
.steampunk-btn:hover {
  transform: translateY(-2px);
  box-shadow:
    0 20px 30px rgba(0, 0, 0, 0.85),
    0 0 15px rgba(255, 170, 0, 0.3);
}

.steampunk-btn:hover .amber-glow {
  opacity: 0.95;
  transform: scale(1.15);
  filter: blur(4px);

  /* Animación de parpadeo continuo activada en hover */
  animation: pulse-amber 1s ease-in-out infinite;
}

.steampunk-btn:hover .btn-text {
  text-shadow:
    0 2px 4px rgba(0, 0, 0, 0.9),
    0 0 16px var(--amber-light);
}

/* Active: Compresión mecánica del botón */
.steampunk-btn:active {
  transform: translateY(1px);
  box-shadow:
    0 5px 10px rgba(0, 0, 0, 0.9),
    inset 0 2px 5px rgba(0, 0, 0, 0.8),
    0 0 35px rgba(252, 153, 15, 0.473),
    0 0 85px rgba(252, 153, 15, 0.29),
    0 0 165px rgba(255, 198, 85, 0.564);
}

