  box-shadow:
    inset 0 3px 6px rgba(0, 0, 0, 0.9),
    inset 0 -1px 2px rgba(255, 255, 255, 0.3);
} */

/* MODIFICACIONES EN ESTADO ACTIVE */

.steampunk-btn:active .amber-glow {
  animation: none; /* Se detiene la animación de parpadeo */
  opacity: 0.9; /* Máxima opacidad */
  transform: scale(1.3); /* Ligeramente más grande */
  filter: blur(15px); /* Un poco más nítido para que se vea más intenso */

  /* Aumentar el brillo del gradiente radial */
  background: radial-gradient(
    circle,
    #ffffff 0%,
    /* Centro blanco para máximo brillo */ var(--amber-light) 30%,
    var(--amber-glow) 60%,
    transparent 80%
  );
}

.steampunk-btn:active .btn-glass {
  /* El vidrio se ilumina cambiando el fondo a uno más claro */
  background: radial-gradient(
    circle at 50% 50%,
    var(--glass-green-bright) 0%,
    #4a3b10 60%,
    /* Tono intermedio más claro */ var(--glass-green-deep) 100%
  );

  /* Sombra interior más intensa y con un ligero tono ámbar */
  box-shadow:
    inset 0 0 10px rgba(0, 0, 0, 1),
    inset 0 0 20px rgba(250, 154, 106, 0.2),
    /* Brillo ámbar interno suave */ 0 0 3px rgba(0, 0, 0, 0.7);
}

@keyframes pulse-amber {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
    filter: blur(6px);
  }
  50% {
    opacity: 0.9;
    transform: scale(1.12);
    filter: blur(4px);
  }
}
